package com.governai.decision;import com.governai.organization.RiskLevel;import tools.jackson.databind.JsonNode;import java.math.BigDecimal;import java.time.OffsetDateTime;import java.util.UUID;public record RecommendationResponse(UUID id,UUID decisionRequestId,String recommendation,String explanation,RiskLevel identifiedRiskLevel,BigDecimal confidenceScore,String modelProvider,String modelName,String modelVersion,String promptVersion,JsonNode metadata,OffsetDateTime generatedAt){public static RecommendationResponse from(AiRecommendation r){return new RecommendationResponse(r.getId(),r.getDecisionRequestId(),r.getRecommendation(),r.getExplanation(),r.getIdentifiedRiskLevel(),r.getConfidenceScore(),r.getModelProvider(),r.getModelName(),r.getModelVersion(),r.getPromptVersion(),r.getMetadata(),r.getGeneratedAt());}}
